z ~=~ \frac{
      \left|\begin{array}{ccc}
        1 & 0 & 1 \\
        0 & e^{t}\cos t & t \\
        0 & -e^{t}\sin t & t^2
      \end{array}\right|
    }{
      \left|\begin{array}{ccc}
        1 & 0 & 0 \\
        0 & e^{t}\cos t & e^{t}\sin t \\
        0 & -e^{t}\sin t & e^{t}\cos t
      \end{array}\right|
    }
    ~=~ \frac{e^t(t^2\cos t - t\sin t)}{e^{2t}}
    ~=~ e^{-t}(t^2\cos t - t\sin t).

