y = \frac{
        \left|\begin{array}{ccc}
          1 & t &  1   \\
          1 & s &  t^2 \\
          1 & 1 &  s^2 \\
        \end{array}\right|
      }{
        \left|\begin{array}{ccc}
          1 & 1 &  1   \\
          1 & t &  t^2 \\
          1 & s &  s^2 \\
        \end{array}\right|
      }
      = \frac{s^3+t^3+1-2-ts^2-t^2}{ts^2+t^2+s-t-st^2-s^2}.
